  ('lesson:smartciti-holodeck/module/airless-sprayer', 'smartciti-holodeck', 'Airless Paint Sprayer Finish', 'worldforge/out/training/smartciti-holodeck.json', E'{"assessment":{"axes":[{"applies_to":["robot","person"],"axis":"coverage","id":"source:coverage","measure":"share of the panel evenly coated (%)","pass":">= 95","status":"measured","verdict":"pass"},{"applies_to":["robot","person"],"axis":"runs","id":"source:runs","measure":"drips from spraying too close or too slow","pass":"== 0","status":"measured","verdict":"pass"},{"applies_to":["robot","person"],"axis":"holidays","id":"source:holidays","measure":"missed spots left uncoated","pass":"== 0","status":"measured","verdict":"pass"},{"applies_to":["robot","person"],"axis":"overspray","id":"source:overspray","measure":"spray drift past the masked boundary","pass":"== 0","status":"measured","verdict":"pass"},{"applies_to":["person"],"axis":"time","id":"source:time","measure":"seconds first spray to last coated cell","pass":"informational","reason":"informational in the source; the simulator has no clock","status":"not measurable in simulation"},{"applies_to":["person"],"axis":"communication","id":"person:communication","reason":"crew communication is taught in the hall''s coordination room; the robot run has no crew","status":"not measurable in simulation"},{"applies_to":["person"],"axis":"judgement","id":"person:judgement","reason":"when to stop, refuse or ask is a person''s call, observed by the instructor; the robot''s equivalent is a mechanical limit check","status":"not measurable in simulation"},{"applies_to":["robot"],"axis":"joint limits","id":"machine:joint-limits","measure":"sweep_x, sweep_y, standoff stay inside their limits on every substep","status":"measured","verdict":"pass"},{"applies_to":["robot"],"axis":"keep-out zones","id":"machine:keep-out-zones","measure":"1 keep-out zone checked on every substep","status":"measured","verdict":"pass"},{"applies_to":["robot"],"axis":"signed run log","id":"ma