  ('lesson:smartciti-holodeck/module/weld-bead', 'smartciti-holodeck', 'Weld Bead Run', 'worldforge/out/training/smartciti-holodeck.json', E'{"assessment":{"axes":[{"applies_to":["robot","person"],"axis":"fusion","id":"source:fusion","measure":"seam segments fused end to end","pass":"== all","status":"measured","verdict":"pass"},{"applies_to":["robot","person"],"axis":"band","id":"source:band","measure":"share of fused segments laid with the gap inside the band (%)","pass":">= 90","status":"measured","verdict":"pass"},{"applies_to":["person"],"axis":"burns","id":"source:burns","measure":"burn-throughs from lingering heat","pass":"== 0","reason":"burn-through comes from dwell time and heat; the simulator has no clock or heat model","status":"not measurable in simulation"},{"applies_to":["person"],"axis":"time","id":"source:time","measure":"seconds first strike to last fuse","pass":"informational","reason":"informational in the source; the simulator has no clock","status":"not measurable in simulation"},{"applies_to":["person"],"axis":"communication","id":"person:communication","reason":"crew communication is taught in the hall''s coordination room; the robot run has no crew","status":"not measurable in simulation"},{"applies_to":["person"],"axis":"judgement","id":"person:judgement","reason":"when to stop, refuse or ask is a person''s call, observed by the instructor; the robot''s equivalent is a mechanical limit check","status":"not measurable in simulation"},{"applies_to":["robot"],"axis":"joint limits","id":"machine:joint-limits","measure":"travel, gap stay inside their limits on every substep","status":"measured","verdict":"pass"},{"applies_to":["robot"],"axis":"signed run log","id":"machine:signed-run-log","measure":"every command is hash-chained and signed by the avatar; the run must re-verify","status":"measured","verdict":"pass"}],"from":"agents/rubrics/index.json#modules[id=smartciti-holodeck.weld-bead].robot_scoring","proposal_status":"awaiting steward approval","rubric_module":"smartciti-holodeck.weld-bead"},"certification":null,"delivered_by":[],"human_track":{"certificate":null,"from":"agents/training/index.json#modules[id=smartciti-holodeck.weld-bead].human","instructor_signoff":"no instructor is registered; this needs a partner","prerequisites":["Complete the Induction & PPE room in your hall (Welding Trades or any paired hall)","Practise the module in the simulator before the instructor session","A human instructor is present for every attempt; the tutor avatar is not an instructor"],"safety_prechecks":[],"steps":[{"do":"Start with every control at its home position.","instructor_checks":"every control is back at its home position","n":1},{"do":"Set the gap at the seam start.","instructor_checks":"the working end is at the marked point; the gap is at its marked setting","n":2},{"do":"Strike the arc.","instructor_checks":"the arc is engaged","n":3},{"do":"Run the bead down the seam.","instructor_checks":"the travel covered the whole marked run with the arc engaged, no gaps; the gap stayed inside its band the whole time the arc was engaged","n":4},{"do":"Break the arc and lift off.","instructor_checks":"the arc is released; the gap is at its marked setting","n":5}],"who":"a person: a trade apprentice"},"id":"lesson:smartciti-holodeck/module/weld-bead","kind":"module","mode":"model-taught","objectives":[{"from":"agents/training/index.json#modules[id=smartciti-holodeck.weld-bead].title","quote":"Weld Bead Run","text":"Run \\"Weld Bead Run\\" step by step, the same steps on both tracks"},{"from":"agents/robotics/index.json#modules[id=smartciti-holodeck.weld-bead].skills[0]","quote":"travel the torch along the seam","text":"Skill: travel the torch along the seam"},{"from":"agents/robotics/index.json#modules[id=smartciti-holodeck.weld-bead].skills[1]","quote":"raise / lower the torch (arc gap)","text":"Skill: raise / lower the torch (arc gap)"},{"from":"agents/robotics/index.json#modules[id=smartciti-holodeck.weld-bead]